import{PROLOGUE_RIVAL as R}from'../development/prologue-rival/fixed-registration.mjs';
const authorities=new WeakMap(),grants=new WeakMap();
const record=(x,keys)=>{if(!x||Object.getPrototypeOf(x)!==Object.prototype||Reflect.ownKeys(x).length!==keys.length)return null;const o={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(x,k);if(!d?.enumerable||!Object.hasOwn(d,'value'))return null;o[k]=d.value}return o};
const exact=(x,y)=>{if(y===null||typeof y!=='object')return x===y;if(!x||typeof x!=='object'||Array.isArray(x)!==Array.isArray(y)||Reflect.ownKeys(x).length!==Reflect.ownKeys(y).length)return false;return Reflect.ownKeys(y).every(k=>{const d=Object.getOwnPropertyDescriptor(x,k);return d&&Object.hasOwn(d,'value')&&exact(d.value,y[k])})};
export function createPrologueRivalAuthority({getWorld,readOwnedApproach,getSignal}={}){if([getWorld,readOwnedApproach,getSignal].some(x=>typeof x!=='function'))throw Error('PROLOGUE_RIVAL_OWNER_REQUIRED');const a=Object.freeze({});authorities.set(a,{getWorld,readOwnedApproach,getSignal});return a}
export const isPrologueRivalAuthority=a=>authorities.has(a);
export const isPrologueRivalRequest=(id,q)=>id===R.sourceRow.id&&record(q,['type'])?.type==='challenge';
function read(a,w){const b=authorities.get(a);if(!b||b.getWorld()!==w||!exact(w.definition.points[R.sourceRow.id],R.sourceRow))return null;const n=record(b.readOwnedApproach(),['sceneId','mapId','revision','imageSHA','maskSHA','artSHA','foot','facing','epoch','ready']);if(!n||n.ready!==true||n.sceneId!==R.sceneId||n.mapId!==R.mapId||n.revision!==R.revision||n.imageSHA!==R.imageSHA||n.maskSHA!==R.maskSHA||n.artSHA!==R.atlas.sha256||n.facing!==R.playerFacing||!Number.isSafeInteger(n.epoch)||n.epoch<0||!Array.isArray(n.foot)||Reflect.ownKeys(n.foot).length!==3)return null;const f=[0,1].map(k=>Object.getOwnPropertyDescriptor(n.foot,String(k)));if(f.some(x=>!x||!Object.hasOwn(x,'value')||!Number.isSafeInteger(x.value)))return null;const[x,y]=f.map(x=>x.value);if(x<=R.npcFoot[0]||Math.abs(x-R.contactCenter[0])+Math.abs(y-R.contactCenter[1])>R.radius||Math.abs(x-R.npcFoot[0])<=48&&Math.abs(y-R.npcFoot[1])<=36)return null;const s=w.snapshot();if(s.position.scene!==R.mapId||s.world.mapId!==R.mapId||!w.story.eventCompleted('P02_FIRST_PARTNER')||!w.story.trainerAvailable('RIVAL_00')&&!s.progress.defeatedTrainers.includes('RIVAL_00'))return null;return{epoch:n.epoch,foot:[x,y],facing:n.facing,sessionId:s.sessionId,revision:s.revision}}
export function mintPrologueRivalGrant(a,w){const p=read(a,w),b=authorities.get(a),signal=b?.getSignal();if(!p||!(signal instanceof AbortSignal)||signal.aborted)throw Error('PROLOGUE_RIVAL_APPROACH_REQUIRED');const g=Object.freeze({});grants.set(g,{a,w,p,signal});return g}
export function assertPrologueRivalGrant(g,w){const q=grants.get(g),b=q&&authorities.get(q.a),p=q&&read(q.a,w);if(!q||q.w!==w||q.signal.aborted||b.getSignal()!==q.signal||!p||!exact(p,q.p))throw Error('PROLOGUE_RIVAL_OWNER_DRIFT')}
export const prologueRivalSignal=(g,w)=>{assertPrologueRivalGrant(g,w);return grants.get(g).signal};
export const revokePrologueRivalGrant=g=>grants.delete(g);
